-- Архив миграции session 75: clp_generic_limits (GCL — пороги Annex I CLP)
-- Источник: .tmp-eurlex/clp-consolidated.html (02008R1272, консолидация 2026-05-01)
-- Применено через MCP: миграция clp_generic_limits_v1 (DDL) + insert.

-- session 75 · GCL — пороги Annex I CLP (generic cut-offs / concentration limits)
create table if not exists public.clp_generic_limits (
  rule_key            text primary key,
  kind                text not null check (kind in (
                        'CUTOFF','GCL','ELICITATION','SUMMATION','M_FACTOR',
                        'RELEVANT','SDS_TRIGGER','VARIATION','PH_RULE',
                        'UNKNOWN_INGREDIENT','SPECIAL')),
  class_code          text not null,           -- обобщённый код класса (ACUTE_TOX, SKIN_CORR_IRRIT, ED_HH …)
  catalog_codes       text[] not null default '{}', -- коды hazard_class_catalog для join
  ghs_chapter         text,                    -- раздел Annex I класса (3.2, 4.1 …)
  ingredient_category text,                    -- как классифицирован компонент (формулировка источника)
  result_category     text,                    -- во что классифицируется смесь
  physical_state      text not null default 'all' check (physical_state in ('all','solid/liquid','gas')),
  operator            text check (operator in ('>=','>','<','<=','>=..<','>..<=')),
  limit_low           numeric,                 -- нижняя граница (для '>=' — сам порог)
  limit_high          numeric,                 -- верхняя граница (для '<'/'<=' — сам порог)
  unit                text,                    -- '%', '% w/w', '% v/v', 'mg/l'
  weight_factor       numeric,                 -- множитель в аддитивной формуле (10, 100)
  value               numeric,                 -- вторичное число: M-фактор, ± % вариации, вязкость
  value_unit          text,
  formula_raw         text,                    -- левая колонка таблицы (сумма/формула) дословно
  raw                 text not null,           -- ячейка/предложение источника дословно
  source_ref          text not null,           -- 'Table 3.2.3' | '3.10.3.3.1.2'
  source_section      text,                    -- пункт, вводящий таблицу
  marker              text,                    -- маркер консолидации: B, M2, M4, M12, M19, M32
  note                text,
  needs_review        boolean not null default false,
  source              text not null default 'CLP 02008R1272 consolidated 2026-05-01, Annex I',
  created_at          timestamptz not null default now()
);
comment on table public.clp_generic_limits is
  'Annex I CLP: generic cut-off values (Table 1.1), generic concentration limits по классам, summation/M-factors (4.1), Table 1.2. Рукотворная таблица, числа только из консолидации 2026-05-01. Session 75.';
create index if not exists clp_generic_limits_class_idx on public.clp_generic_limits (class_code, kind);
create index if not exists clp_generic_limits_catalog_idx on public.clp_generic_limits using gin (catalog_codes);
alter table public.clp_generic_limits enable row level security;
drop policy if exists "public read" on public.clp_generic_limits;
create policy "public read" on public.clp_generic_limits for select using (true);

on conflict (rule_key) do update set kind=excluded.kind, class_code=excluded.class_code, catalog_codes=excluded.catalog_codes, ghs_chapter=excluded.ghs_chapter, ingredient_category=excluded.ingredient_category, result_category=excluded.result_category, physical_state=excluded.physical_state, operator=excluded.operator, limit_low=excluded.limit_low, limit_high=excluded.limit_high, unit=excluded.unit, weight_factor=excluded.weight_factor, value=excluded.value, value_unit=excluded.value_unit, formula_raw=excluded.formula_raw, raw=excluded.raw, source_ref=excluded.source_ref, source_section=excluded.source_section, marker=excluded.marker, note=excluded.note, needs_review=excluded.needs_review;
