('3.1.3.3a-RELEVANT', 'RELEVANT', 'ACUTE_TOX', '{ACUTE_TOX_ORAL,ACUTE_TOX_DERMAL,ACUTE_TOX_INHAL}', '3.1', 'any ingredient (acute toxicity)', null, 'all', '>=', 1, null, '% (w/w solids, liquids, dusts, mists, vapours; v/v gases)', null, null, null, null, 'the ‘relevant ingredients’ of a mixture are those which are present in concentrations of 1 % (w/w for solids, liquids, dusts, mists and vapours and v/v for gases) or greater, unless there is a reason to suspect that an ingredient present at a concentration of less than 1 % is still relevant for classifying the mixture for acute toxicity (see Table 1.1).', '3.1.3.3(a)', '3.1.3.3', 'B', null, false),
('3.1.3.6.2.2-UNKNOWN', 'UNKNOWN_INGREDIENT', 'ACUTE_TOX', '{ACUTE_TOX_ORAL,ACUTE_TOX_DERMAL,ACUTE_TOX_INHAL}', '3.1', 'component without any useable information', null, 'all', '>=', 1, null, '%', null, null, null, null, 'In the event that a component without any useable information for classification is used in a mixture at a concentration ≥ 1 %, it is concluded that the mixture cannot be attributed a definitive acute toxicity estimate. In this situation the mixture shall be classified based on the known components only, with the additional statement on the label and in the SDS that ‘x per cent of the mixture consists of component(s) of unknown acute toxicity’, taking into account the provisions set out in section 3.1.4.2.', '3.1.3.6.2.2', '3.1.3.6.2', 'M4', null, false),
('3.1.3.6.2.3-UNKNOWN-LE10', 'UNKNOWN_INGREDIENT', 'ACUTE_TOX', '{ACUTE_TOX_ORAL,ACUTE_TOX_DERMAL,ACUTE_TOX_INHAL}', '3.1', 'total of relevant ingredient(s) with unknown acute toxicity', null, 'all', '<=', null, 10, '%', null, null, null, null, 'If the total concentration of the relevant ingredient(s) with unknown acute toxicity is ≤ 10 % then the formula presented in section 3.1.3.6.1 shall be used.', '3.1.3.6.2.3', '3.1.3.6.2', 'M4', null, false),
('3.1.3.6.2.3-UNKNOWN-GT10', 'UNKNOWN_INGREDIENT', 'ACUTE_TOX', '{ACUTE_TOX_ORAL,ACUTE_TOX_DERMAL,ACUTE_TOX_INHAL}', '3.1', 'total of relevant ingredient(s) with unknown acute toxicity', null, 'all', '>', 10, null, '%', null, null, null, '(100 − Σ C_unknown) / ATE_mix = Σ (C_i / ATE_i)', 'If the total concentration of the relevant ingredient(s) with unknown toxicity is > 10 %, the formula presented in section 3.1.3.6.1 shall be corrected to adjust for the percentage of the unknown ingredient(s)', '3.1.3.6.2.3', '3.1.3.6.2', 'M4', 'Формула в источнике дана картинкой/формулой; в formula_raw — общепринятая запись скорректированной формулы 3.1.3.6.1, сверить с ate.ts.', true),
('T3.2.3-CORR-SUM-GE5', 'GCL', 'SKIN_CORR_IRRIT', '{SKIN_CORR_IRRIT}', '3.2', 'Skin corrosion Sub-Category 1A, 1B, 1C or Category 1', 'Skin corrosion Category 1 (see note below)', 'all', '>=', 5, null, '%', null, null, null, 'Sum of Skin corrosion Sub-Category 1A, 1B, 1C or Category 1', 'Skin corrosion Sub-Category 1A, 1B, 1C or Category 1 | ≥ 5 % | ≥ 1 % but < 5 %', 'Table 3.2.3', '3.2.3.3.3', 'M12', 'Note: The sum of all ingredients of a mixture classified as Skin Corrosion Sub-Category 1A, 1B, or 1C respectively, shall each be ≥ 5 % in order to classify the mixture as either Skin Corrosion Sub-Category 1A, 1B or 1C. If the sum of the ingredients classified as Skin Corrosion Sub-Category 1A is < 5 % but the sum of ingredients classified as Skin Corrosion Sub-Category 1A + 1B is ≥ 5 %, the mixture shall be classified as Skin Corrosion Sub-Category 1B. Similarly, if the sum of ingredients classified as Skin Corrosion Sub-Category 1A + 1B ingredients is < 5 % but the sum of ingredients classified as Sub-Category 1A + 1B + 1C is ≥ 5 % the mixture shall be classified as Skin Corrosion Sub-Category 1C. Where at least one relevant ingredient in a mixture is classified as Category 1 without sub-categorisation, the mixture shall be classified as Category 1 without sub-categorisation if the sum of all ingredients corrosive to skin is ≥ 5 %.', false),
('T3.2.3-CORR-SUM-1-5', 'GCL', 'SKIN_CORR_IRRIT', '{SKIN_CORR_IRRIT}', '3.2', 'Skin corrosion Sub-Category 1A, 1B, 1C or Category 1', 'Skin irritation Category 2', 'all', '>=..<', 1, 5, '%', null, null, null, 'Sum of Skin corrosion Sub-Category 1A, 1B, 1C or Category 1', 'Skin corrosion Sub-Category 1A, 1B, 1C or Category 1 | ≥ 5 % | ≥ 1 % but < 5 %', 'Table 3.2.3', '3.2.3.3.3', 'M12', null, false),
('T3.2.3-IRRIT-SUM-GE10', 'GCL', 'SKIN_CORR_IRRIT', '{SKIN_CORR_IRRIT}', '3.2', 'Skin irritation Category 2', 'Skin irritation Category 2', 'all', '>=', 10, null, '%', null, null, null, 'Sum of Skin irritation Category 2', 'Skin irritation Category 2 | | ≥ 10 %', 'Table 3.2.3', '3.2.3.3.3', 'M12', null, false),
('T3.2.3-WEIGHTED-GE10', 'GCL', 'SKIN_CORR_IRRIT', '{SKIN_CORR_IRRIT}', '3.2', '(10 × Skin corrosion Sub-Category 1A, 1B, 1C or Category 1) + Skin irritation Category 2', 'Skin irritation Category 2', 'all', '>=', 10, null, '%', 10, null, null, '(10 × Skin corrosion Sub-Category 1A, 1B, 1C or Category 1) + Skin irritation Category 2', '(10 × Skin corrosion Sub-Category 1A, 1B, 1C or Category 1) + Skin irritation Category 2 | | ≥ 10 %', 'Table 3.2.3', '3.2.3.3.3', 'M12', null, false),
('T3.2.4-ACID', 'GCL', 'SKIN_CORR_IRRIT', '{SKIN_CORR_IRRIT}', '3.2', 'Acid with pH ≤ 2', 'Skin corrosion Category 1', 'all', '>=', 1, null, '%', null, null, null, null, 'Acid with pH ≤ 2 | ≥ 1 % | Skin corrosion Category 1', 'Table 3.2.4', '3.2.3.3.4.3', 'M12', 'additivity approach does not apply', false),
('T3.2.4-BASE', 'GCL', 'SKIN_CORR_IRRIT', '{SKIN_CORR_IRRIT}', '3.2', 'Base with pH ≥ 11,5', 'Skin corrosion Category 1', 'all', '>=', 1, null, '%', null, null, null, null, 'Base with pH ≥ 11,5 | ≥ 1 % | Skin corrosion Category 1', 'Table 3.2.4', '3.2.3.3.4.3', 'M12', 'additivity approach does not apply', false),
('T3.2.4-OTHER-CORR', 'GCL', 'SKIN_CORR_IRRIT', '{SKIN_CORR_IRRIT}', '3.2', 'Other skin corrosive (Sub-Categories 1A, 1B, 1C or Category 1) ingredients', 'Skin corrosion Category 1', 'all', '>=', 1, null, '%', null, null, null, null, 'Other skin corrosive (Sub-Categories 1A, 1B, 1C or Category 1) ingredients | ≥ 1 % | Skin corrosion Category 1', 'Table 3.2.4', '3.2.3.3.4.3', 'M12', 'additivity approach does not apply', false),
('T3.2.4-OTHER-IRRIT', 'GCL', 'SKIN_CORR_IRRIT', '{SKIN_CORR_IRRIT}', '3.2', 'Other skin irritant (Category 2) ingredients, including acids and bases', 'Skin irritation Category 2', 'all', '>=', 3, null, '%', null, null, null, null, 'Other skin irritant (Category 2) ingredients, including acids and bases | ≥ 3 % | Skin irritation Category 2', 'Table 3.2.4', '3.2.3.3.4.3', 'M12', 'additivity approach does not apply', false),
('3.2.3.1.2-PH', 'PH_RULE', 'SKIN_CORR_IRRIT', '{SKIN_CORR_IRRIT}', '3.2', 'mixture as a whole (pH)', 'Skin Corrosion Category 1', 'all', null, null, null, 'pH', null, null, null, 'pH ≤ 2 or pH ≥ 11,5', 'In the absence of any other information, a mixture is considered corrosive to skin (Skin Corrosion Category 1) if it has a pH ≤ 2 or a pH ≥ 11,5. However, if consideration of acid/alkaline reserve suggests the mixture may not be corrosive despite the low or high pH value, this needs to be confirmed by other data, preferably by data from an appropriate validated in vitro test.', '3.2.3.1.2', '3.2.3.1', 'M12', null, false),
('3.2.3.3.6-LOWER', 'SPECIAL', 'SKIN_CORR_IRRIT', '{SKIN_CORR_IRRIT}', '3.2', 'ingredient with data showing effect below GCL', null, 'all', '<', null, 1, '%', null, null, null, null, 'If there are data showing that (an) ingredient(s) is/are corrosive or irritant to skin at a concentration of < 1 % (skin corrosive) or < 3 % (skin irritant), the mixture shall be classified accordingly.', '3.2.3.3.6', '3.2.3.3', 'M12', '< 1 % skin corrosive; < 3 % skin irritant. Это ссылка сноски (1) Table 1.1.', false),
('T3.3.3-CORR+DAM-SUM-GE3', 'GCL', 'EYE_DAMAGE_IRRIT', '{EYE_DAMAGE_IRRIT}', '3.3', 'Skin corrosion Sub-Category 1A, 1B, 1C or Category 1 + Serious eye damage (Category 1) (1)', 'Serious eye damage Category 1', 'all', '>=', 3, null, '%', null, null, null, 'Sum of Skin corrosion Sub-Category 1A, 1B, 1C or Category 1 + Serious eye damage (Category 1)', 'Skin corrosion Sub-Category 1A, 1B, 1C or Category 1 + Serious eye damage (Category 1) ( ) | ≥ 3 % | ≥ 1 % but < 3 %', 'Table 3.3.3', '3.3.3.3.3', 'M12', '(1) If an ingredient is classified as both Skin Corrosion Sub-Category 1A, 1B, 1C or Category 1 and Serious Eye Damage (Category 1), its concentration is considered only once in the calculation.', false),
('T3.3.3-CORR+DAM-SUM-1-3', 'GCL', 'EYE_DAMAGE_IRRIT', '{EYE_DAMAGE_IRRIT}', '3.3', 'Skin corrosion Sub-Category 1A, 1B, 1C or Category 1 + Serious eye damage (Category 1) (1)', 'Eye irritation Category 2', 'all', '>=..<', 1, 3, '%', null, null, null, 'Sum of Skin corrosion Sub-Category 1A, 1B, 1C or Category 1 + Serious eye damage (Category 1)', 'Skin corrosion Sub-Category 1A, 1B, 1C or Category 1 + Serious eye damage (Category 1) ( ) | ≥ 3 % | ≥ 1 % but < 3 %', 'Table 3.3.3', '3.3.3.3.3', 'M12', '(1) If an ingredient is classified as both Skin Corrosion Sub-Category 1A, 1B, 1C or Category 1 and Serious Eye Damage (Category 1), its concentration is considered only once in the calculation.', false),
('T3.3.3-IRRIT-SUM-GE10', 'GCL', 'EYE_DAMAGE_IRRIT', '{EYE_DAMAGE_IRRIT}', '3.3', 'Eye irritation (Category 2)', 'Eye irritation Category 2', 'all', '>=', 10, null, '%', null, null, null, 'Sum of Eye irritation (Category 2)', 'Eye irritation (Category 2) | | ≥ 10 %', 'Table 3.3.3', '3.3.3.3.3', 'M12', null, false),
('T3.3.3-WEIGHTED-GE10', 'GCL', 'EYE_DAMAGE_IRRIT', '{EYE_DAMAGE_IRRIT}', '3.3', '10 × (Skin corrosion Sub-Category 1A, 1B, 1C or Skin corrosion Category 1 + Serious eye damage (Category 1)) + Eye irritation (Category 2)', 'Eye irritation Category 2', 'all', '>=', 10, null, '%', 10, null, null, '10 × (Skin corrosion Sub-Category 1A, 1B, 1C or Skin corrosion Category 1 + Serious eye damage (Category 1)) + Eye irritation (Category 2)', '10 × (Skin corrosion Sub-Category 1A, 1B, 1C or Skin corrosion Category 1 + Serious eye damage (Category 1)) + Eye irritation (Category 2) | | ≥ 10 %', 'Table 3.3.3', '3.3.3.3.3', 'M12', null, false),
('T3.3.4-ACID', 'GCL', 'EYE_DAMAGE_IRRIT', '{EYE_DAMAGE_IRRIT}', '3.3', 'Acid with pH ≤ 2', 'Serious eye damage (Category 1)', 'all', '>=', 1, null, '%', null, null, null, null, 'Acid with pH ≤ 2 | ≥ 1 % | Serious eye damage (Category 1)', 'Table 3.3.4', '3.3.3.3.4.3', 'M12', 'additivity approach does not apply', false),
('T3.3.4-BASE', 'GCL', 'EYE_DAMAGE_IRRIT', '{EYE_DAMAGE_IRRIT}', '3.3', 'Base with pH ≥ 11,5', 'Serious eye damage (Category 1)', 'all', '>=', 1, null, '%', null, null, null, null, 'Base with pH ≥ 11,5 | ≥ 1 % | Serious eye damage (Category 1)', 'Table 3.3.4', '3.3.3.3.4.3', 'M12', 'additivity approach does not apply', false),
('T3.3.4-OTHER-CORR-DAM', 'GCL', 'EYE_DAMAGE_IRRIT', '{EYE_DAMAGE_IRRIT}', '3.3', 'Other ingredient classified as skin corrosion (Sub-Category 1A, 1B, 1C or Category 1) or serious eye damage (Category 1)', 'Serious eye damage (Category 1)', 'all', '>=', 1, null, '%', null, null, null, null, 'Other ingredient classified as skin corrosion (Sub-Category 1A, 1B, 1C or Category 1) or serious eye damage (Category 1) | ≥ 1 % | Serious eye damage (Category 1)', 'Table 3.3.4', '3.3.3.3.4.3', 'M12', 'additivity approach does not apply', false),
('T3.3.4-OTHER-IRRIT', 'GCL', 'EYE_DAMAGE_IRRIT', '{EYE_DAMAGE_IRRIT}', '3.3', 'Other ingredient classified as eye irritation (Category 2)', 'Eye irritation (Category 2)', 'all', '>=', 3, null, '%', null, null, null, null, 'Other ingredient classified as eye irritation (Category 2) | ≥ 3 % | Eye irritation (Category 2)', 'Table 3.3.4', '3.3.3.3.4.3', 'M12', 'additivity approach does not apply', false),
('3.3.3.1.2-PH', 'PH_RULE', 'EYE_DAMAGE_IRRIT', '{EYE_DAMAGE_IRRIT}', '3.3', 'mixture as a whole (pH)', 'Serious eye damage (Category 1)', 'all', null, null, null, 'pH', null, null, null, 'pH ≤ 2 or pH ≥ 11,5', 'In the absence of any other information, a mixture is considered to cause serious eye damage (Category 1) if it has a pH ≤ 2 or ≥ 11,5. However, if consideration of acid/alkali reserve suggests the mixture may not cause serious eye damage despite the low or high pH value, this needs to be confirmed by other data, preferably data from an appropriate validated in vitro test.', '3.3.3.1.2', '3.3.3.1', 'M12', null, false),
('3.3.3.3.6-LOWER', 'SPECIAL', 'EYE_DAMAGE_IRRIT', '{EYE_DAMAGE_IRRIT}', '3.3', 'ingredient with data showing effect below GCL', null, 'all', '<', null, 1, '%', null, null, null, null, 'If there are data showing that (an) ingredient(s) may be corrosive to the skin or seriously damaging to the eye/eye irritating at a concentration of < 1 % (corrosive to the skin or seriously damaging to the eye) or < 3 % (eye irritant), the mixture shall be classified accordingly.', '3.3.3.3.6', '3.3.3.3', 'M12', '< 1 % corrosive/serious eye damage; < 3 % eye irritant. Это ссылка сноски (2) Table 1.1.', false),
('T3.4.5-RESP1-SL', 'GCL', 'RESP_SENS', '{RESP_SENS}', '3.4', 'Respiratory sensitiser Category 1', 'Respiratory sensitiser Category 1', 'solid/liquid', '>=', 1.0, null, '%', null, null, null, null, 'Respiratory sensitiser Category 1 | ≥ 1,0 % | ≥ 0,2 % |', 'Table 3.4.5', '3.4.3.3.1', 'M2', 'columns: Solid/liquid | Gas | All physical states', false),
('T3.4.6-RESP1-SL', 'ELICITATION', 'RESP_SENS', '{RESP_SENS}', '3.4', 'Respiratory sensitiser Category 1', 'Respiratory sensitiser Category 1 (elicitation; Annex II 2.8)', 'solid/liquid', '>=', 0.1, null, '%', null, null, null, null, 'Respiratory sensitiser Category 1 | ≥ 0,1 % (Note 1) | ≥ 0,1 % (Note 1) |', 'Table 3.4.6', '3.4.3.3.2', 'M2', 'Note 1 (▼M19): This concentration limit for elicitation is used for the application of the special labelling requirements of section 2.8 of Annex II to protect already sensitised individuals. A SDS is required for the mixture containing a component at or above this concentration. For sensitising substances with a specific concentration limit, the concentration limit for elicitation shall be set at a tenth of the specific concentration limit.', false),
('T3.4.5-RESP1-GAS', 'GCL', 'RESP_SENS', '{RESP_SENS}', '3.4', 'Respiratory sensitiser Category 1', 'Respiratory sensitiser Category 1', 'gas', '>=', 0.2, null, '%', null, null, null, null, 'Respiratory sensitiser Category 1 | ≥ 1,0 % | ≥ 0,2 % |', 'Table 3.4.5', '3.4.3.3.1', 'M2', 'columns: Solid/liquid | Gas | All physical states', false),
('T3.4.6-RESP1-GAS', 'ELICITATION', 'RESP_SENS', '{RESP_SENS}', '3.4', 'Respiratory sensitiser Category 1', 'Respiratory sensitiser Category 1 (elicitation; Annex II 2.8)', 'gas', '>=', 0.1, null, '%', null, null, null, null, 'Respiratory sensitiser Category 1 | ≥ 0,1 % (Note 1) | ≥ 0,1 % (Note 1) |', 'Table 3.4.6', '3.4.3.3.2', 'M2', 'Note 1 (▼M19): This concentration limit for elicitation is used for the application of the special labelling requirements of section 2.8 of Annex II to protect already sensitised individuals. A SDS is required for the mixture containing a component at or above this concentration. For sensitising substances with a specific concentration limit, the concentration limit for elicitation shall be set at a tenth of the specific concentration limit.', false),
